package ai.interviewiq.api.controller; import ai.interviewiq.api.dto.InterviewDtos.*; import ai.interviewiq.api.entity.InterviewStatus; import ai.interviewiq.api.service.InterviewService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/interview-sessions") public class InterviewController {final InterviewService s; final ai.interviewiq.api.service.PdfReportService pdf;public InterviewController(InterviewService i,ai.interviewiq.api.service.PdfReportService p){s=i;pdf=p;}private Long uid(Authentication a){return(Long)a.getPrincipal();}@PostMapping @ResponseStatus(HttpStatus.CREATED) SessionResponse create(Authentication a,@Valid @RequestBody CreateRequest r){return s.create(uid(a),r);}@GetMapping PageResponse<SessionResponse> history(Authentication a,@RequestParam(required=false) InterviewStatus status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int limit){return s.history(uid(a),status,page,limit);}@GetMapping("/{id}") SessionResponse get(Authentication a,@PathVariable Long id){return s.get(uid(a),id);}@PostMapping("/{id}/start") SessionResponse start(Authentication a,@PathVariable Long id){return s.start(uid(a),id);}@GetMapping("/{id}/questions") List<QuestionResponse> questions(Authentication a,@PathVariable Long id){return s.questions(uid(a),id);}@PutMapping("/{id}/questions/{questionId}/answer") AnswerResponse answer(Authentication a,@PathVariable Long id,@PathVariable Long questionId,@Valid @RequestBody AnswerRequest r){return s.answer(uid(a),id,questionId,r);}@PostMapping("/{id}/complete") @ResponseStatus(HttpStatus.ACCEPTED) FeedbackResponse complete(Authentication a,@PathVariable Long id){return s.complete(uid(a),id);}@GetMapping("/{id}/feedback") FeedbackResponse feedback(Authentication a,@PathVariable Long id){return s.feedback(uid(a),id);}@GetMapping(value="/{id}/report/pdf",produces="application/pdf") ResponseEntity<byte[]> pdf(Authentication a,@PathVariable Long id){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=interviewiq-report-"+id+".pdf").body(pdf.generate(uid(a),id));}}
